<script lang="ts">
  import ObjectiveWindow from '$lib/ObjectiveWindow.svelte';
  import { invalidateAll } from '$app/navigation';
  let { data } = $props();
  let message = $state(''); let problem = $state(''); let busy = $state(false); let commitMessage = $state('Update objective working state'); let showGit = $state(false);
  async function action(name: string) {
    if (name === 'push' && !confirm('Push the current branch to its configured Git upstream?')) return;
    busy = true; problem = ''; message = '';
    try { const response = await fetch('/api/action', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action: name, message: commitMessage }) }); const body = await response.json(); if (!response.ok) throw new Error(body.error); message = name === 'commit' ? 'Objective changes committed locally.' : 'Branch pushed to its upstream.'; await invalidateAll(); } catch (e) { problem = (e as Error).message; } finally { busy = false; }
  }
</script>
<svelte:head><title>{data.objective.title} · Oasis Graph Browser</title><meta name="description" content="Operate your living objective graph. Explore, edit, and commit your work."/></svelte:head>
<div class="app-shell">
  <aside><a class="brand" href="/"><span class="logo">O</span> oasis</a><div class="rail-label">RESEARCH LABORATORY</div><nav><a href="/" class="active">◉ &nbsp; Objective graph</a><button onclick={() => showGit = !showGit}>⑂ &nbsp; Git workspace</button></nav><div class="rail-bottom"><span class="live-dot"></span> Local workspace<p>Warm room.<br/>Cold math.</p><small>GRAPH BROWSER / MVP</small></div></aside>
  <main><div class="topbar"><div class="breadcrumb"><a href="/">Oasis</a>{#each data.objective.path.split('/').filter(Boolean) as part}<span>/</span><span>{part}</span>{/each}</div><button class="git-chip" onclick={() => showGit = !showGit}>⑂ {data.git.branch || 'detached'} <span>{data.git.head}</span></button></div>
    <section class="intro"><div><div class="eyebrow">THE ORGANIZATION, IN MOTION</div><h1>Your work is a living graph.</h1><p>Open a branch. Follow the objective. Leave evidence.</p></div><span class="local-badge"><span class="live-dot"></span> Filesystem connected</span></section>
    {#if showGit}<section class="git-panel"><div><h2>Git workspace</h2><p>Saves write to disk. Commits record objective changes. Push publishes committed history.</p></div><pre>{data.git.changes || 'Working tree clean'}</pre><label for="commit">Commit message</label><div class="git-actions"><input id="commit" bind:value={commitMessage}/><button class="primary" disabled={busy} onclick={() => action('commit')}>Commit objectives</button><button disabled={busy} onclick={() => action('push')}>Push upstream</button></div></section>{/if}
    {#if message}<p class="notice" role="status">{message}</p>{/if}{#if problem}<p class="error" role="alert">{problem}</p>{/if}
    {#key data.objective.path}<ObjectiveWindow node={data.objective} top onSaved={(text) => message = text}/>{/key}
    <footer><span>Intent → action → evidence</span><span>Git is the source of truth.</span></footer>
  </main>
</div>
